import{z as i,x as A,o,c as B,q as t,j as s,D as e,d as E,s as r,S as p,b as l}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"SDN 与 OpenFlow","description":"","frontmatter":{"title":"SDN 与 OpenFlow","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sdn-openflow.md","filePath":"cs/sdn-openflow.md","lastUpdated":1791063341000}'),d={name:"cs/sdn-openflow.md"};function D(C,a,F,m,c,h){const n=A("Mermaid");return o(),B("div",null,[a[2]||(a[2]=t('<h1 id="sdn-与-openflow" tabindex="-1">SDN 与 OpenFlow <a class="header-anchor" href="#sdn-与-openflow" aria-label="Permalink to &quot;SDN 与 OpenFlow&quot;">​</a></h1><div class="epigraph"><p>控制面从盒内协议簇里抽到控制器，交换机按流表匹配-动作转发；OpenFlow 是这条南向的一个历史接口。</p><footer>—— 据 McKeown et al., OpenFlow, ACM SIGCOMM CCR 2008；RFC 7426 SDN 层整理</footer></div><p><a href="/cs/tcam-lookup">上一课</a> 给出流表的硬件形状。传统盒内 BGP/OSPF 自闭环。缺口是 <strong>SDN 分工</strong>：控制器算全局，南向装表。本课不把 P4 语言写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TE 与 ACL 在分布式协议里用属性暗示，难全局最优。SDN：逻辑中心看全拓扑，下发精确匹配。OpenFlow：匹配域（端口、MAC、IP、TCP）→ 动作（出端口、改头、去控制器）。失败模式：控制器分区、表满、反应式首包上送变成慢路径洪水。与 RR 对照：都是控制面中心化，OpenFlow 更细到每流。<span class="marginnote">「匹配-动作」翻译成大白话：交换机不再自带「怎么路由」的判断力，只执行「凡是长成这样的包就从那个口丢出去」的规则——规则本身由控制器统一算好送来。</span></p><p>不要把 SDN 写成「不用 BGP」的互联网替代：域间仍政策。</p><p><span class="marginnote">OpenFlow 交换机规范多版本。RFC 7426 分层。本课不把每个 match 字段列完。</span></p><h3 id="南向之一不是互联网替代" tabindex="-1">南向之一不是互联网替代 <a class="header-anchor" href="#南向之一不是互联网替代" aria-label="Permalink to &quot;南向之一不是互联网替代&quot;">​</a></h3><p>控制器装流表，交换机匹配-动作。表满与控制器分区是失败模式。域间仍政策。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：控制器 → OpenFlow → 多级流表 → 流水线。对照 RIB/FIB：控制器相当于外置 RP。主动装表 vs 首包上送。</p>',11)),(o(),s(p,null,{default:e(()=>[r(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTL%5B%22%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%20--%3E%20OF%5B%22OpenFlow%22%5D%0A%20%20OF%20--%3E%20FT%5B%22%E6%B5%81%E8%A1%A8%20TCAM%22%5D%0A%20%20FT%20--%3E%20FWD%5B%22%E5%8C%B9%E9%85%8D%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20MISS%5B%22%E6%9C%AA%E5%91%BD%E4%B8%AD%22%5D%20--%3E%20CTL%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[E("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"数据中心 Clos 可用 SDN 做负载与租户隔离，或用 BGP EVPN 做同一件事——两条工程路径。PFC 仍在数据面。安全：控制器被冒充则全网被改，南向要 TLS，对象与 BGP 认证同类。",-1)),a[5]||(a[5]=l("p",null,"反应式装表的慢路径长这样：流表未命中的第一个包被上送控制器，控制器算好路径再下发规则，此后同类包走快路径。",-1)),(o(),s(p,null,{default:e(()=>[r(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%A6%96%E5%8C%85%E5%88%B0%E8%BE%BE%E4%BA%A4%E6%8D%A2%E6%9C%BA%22%5D%20--%3E%20T%7B%22%E9%80%90%E7%BA%A7%E6%9F%A5%E6%B5%81%E8%A1%A8%22%7D%0A%20%20T%20--%20%22%E5%91%BD%E4%B8%AD%22%20--%3E%20F%5B%22%E6%8C%89%E5%8A%A8%E4%BD%9C%E7%9B%B4%E6%8E%A5%E8%BD%AC%E5%8F%91%EF%BC%9A%E5%BF%AB%E8%B7%AF%E5%BE%84%22%5D%0A%20%20T%20--%20%22%E6%9C%AA%E5%91%BD%E4%B8%AD%22%20--%3E%20PI%5B%22%E5%B0%81%E8%A3%85%20Packet-In%20%E4%B8%8A%E9%80%81%22%5D%0A%20%20PI%20--%3E%20C%5B%22%E6%8E%A7%E5%88%B6%E5%99%A8%E6%9F%A5%E5%85%A8%E5%B1%80%E6%8B%93%E6%89%91%E7%AE%97%E8%B7%AF%E5%BE%84%22%5D%0A%20%20C%20--%3E%20FM%5B%22%E4%B8%8B%E5%8F%91%20Flow-Mod%20%E5%86%99%E5%85%A5%E6%B5%81%E8%A1%A8%22%5D%0A%20%20FM%20--%3E%20F%0A%20%20C%20-.%20%22%E5%90%8E%E7%BB%AD%E5%90%8C%E7%B1%BB%E5%8C%85%E5%91%BD%E4%B8%AD%E6%96%B0%E8%A7%84%E5%88%99%22%20.-%3E%20F%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>与 Saltzer：中心控制是性能与政策优化，正确性仍要端到端。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 OVSDB/NETCONF 的全部。P4 可编程是下一课。后课默认：SDN = 控制/转发分离；OpenFlow 是南向之一。<span class="marginnote">数字实例：一台交换机 TCAM 通常只有几千条流表项，而一个数据中心活跃「流」（五元组会话）常以百万计——所以控制器必须做流聚合（按前缀/租户合并规则），否则表满即丢规则。</span></p><p>反应式 SDN 在广域高 RTT（卫星）上首包延迟不可接受，应主动装表。<span class="marginnote">常见误区：初学者容易以为「每条流都要控制器过一遍手」是 SDN 的本性——实际上那是反应式（被动装表）模式；主动装表可以在流量到来之前就把规则铺好，交换机全程不问控制器。</span></p><p>下一课<a href="/cs/p4-programmable">P4 可编程</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>控制器装流表，交换机执行匹配-动作。</li><li>表容量与控制器可用是边界。</li><li>不自动取消域间 BGP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：McKeown et al., 2008；RFC 7426。</li></ul>',7))])}const T=i(d,[["render",D]]);export{P as __pageData,T as default};
